import bcrypt from 'bcrypt';
const hash = await bcrypt.hash(password, 12);   // 솔트 포함 · 의도적으로 느리다
await bcrypt.compare(input, hash);

// SHA-256 은 비밀번호용이 아니다 — 너무 빨라 무차별 대입에 약하다

res.cookie('session', id, {
  httpOnly: true,   // JS 에서 못 읽는다
  secure: true,     // https 에서만
  sameSite: 'lax',  // 다른 사이트에서 온 요청에는 제한적으로만
  maxAge: 1000 * 60 * 60 * 24 * 14,
});

// 로그인만 확인하면 남의 주문이 보인다
if (!req.user) return res.sendStatus(401);
const order = await findOrder(req.params.id);

// 자원 소유까지 확인해야 한다
if (order.userId !== req.user.id) return res.sendStatus(404);   // 존재 여부도 숨긴다
